        } catch (SQLException e) {
            // 5. ___ decide how to handle the exception ___
            // e.g. throw new IllegalStateException("…", e);
        }
    }

    // 3. public accessor with lazy initialisation
    public static DatabaseConnectionManager getInstance() {
        if (instance == null) {               // first check
            synchronized (LOCK) {
                if (instance == null) {       // second check
                    // 4. ___ create the singleton ___
                    instance = new DatabaseConnectionManager();
                }
            }
        }
        return instance;
    }

    // 6. expose the connection
    public Connection getConnection() {
        // ___ decide what to do if `connection` is null because construction failed ___
        return connection;
    }

    // 7. optional cleanup
